KG42.register("clusters-6554e72189d1f47c12738bff",{"id":"42-data_center_space_time_flexibility::v142-d-K005","paper":"42-data_center_space_time_flexibility","label":"Candidate for temporal load-shifting declaration, clearing, and remuneration at a single spatial node","record":{"cluster_id":"v142-d-K005","label":"Candidate for temporal load-shifting declaration, clearing, and remuneration at a single spatial node","market_meaning":"DaCe and the suppliers declare prices and capacities over time; clearing selects the load, generation, and load shifting toward the future in each period, arranges the service under computing-capacity and virtual-capacity constraints, and settles by the temporal price and the sending-minus-receiving price difference. Revenue adequacy of the reported cases and revenue adequacy of the general model each retain their own scope of applicability.","mechanism_ids":["v141-a-M05"],"market_types":["DEM"],"process_stages":["bidding","clearing","settlement"],"scope_disposition":"unresolved","scope_explanation":"Restricted to the model with a single spatial node, no transmission network, and temporal links directed toward the future. General temporal clearing and the Table 5 results, which contain additional case conditions, cannot be equated unconditionally; the load-shifting signs in the two B citations of (2.31b) are opposite.","assembly_status":"partial","boundary_rationale":"The temporal quoted price, the load-shifting quota, and the price-difference remuneration have a direct quantity dependence and constitute a candidate temporal flexibility service; the sign conflict and the missing objective expression mean that it has not yet formed a closed rule.","chain_bindings":[{"chain_id":"v141-c-R015","ownership":"primary","role":"interface","rationale":"Retains the fact of the hourly demand declaration and does not restore the rejected mathematical object."},{"chain_id":"v141-c-R016","ownership":"primary","role":"interface","rationale":"Provides the hourly supply quoted price and capacity."},{"chain_id":"v141-c-R017","ownership":"primary","role":"core","rationale":"Determines the temporal quota and load-shifting feasibility, while retaining the gaps in the objective and in the definitions."},{"chain_id":"v141-c-R018","ownership":"primary","role":"core","rationale":"Specifies the temporal-price remuneration and records the case revenue reconciliation."}],"connections":[{"connection_id":"v142-d-K005-J01","from_chain_id":"v141-c-R015","to_chain_id":"v141-c-R017","kind":"functional_coupling","from_refs":["v141-c-R015::phi::v141-c-R015-C001"],"to_refs":["v141-c-R017::theta::v141-c-R017-theta-alpha_d_t","v141-c-R017::theta::v141-c-R017-theta-bar_d_t","v141-c-R017::phi::v141-c-R017-C001"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"],"rationale":"The same temporal demand declaration gives the value and the upper bound of the cleared demand; R015 has no parameter object available for a same-quantity mapping."},{"connection_id":"v142-d-K005-J02","from_chain_id":"v141-c-R016","to_chain_id":"v141-c-R017","kind":"quantity_interface","from_refs":["v141-c-R016::theta::v141-c-R016-TH001","v141-c-R016::theta::v141-c-R016-TH002"],"to_refs":["v141-c-R017::theta::v141-c-R017-theta-alpha_p_t","v141-c-R017::theta::v141-c-R017-theta-bar_p_t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037","v141-b-g03-E06"],"rationale":"The temporal supply declaration serves as the clearing-price coefficient and the generation-capacity input."},{"connection_id":"v142-d-K005-J03","from_chain_id":"v141-c-R017","to_chain_id":"v141-c-R018","kind":"quantity_interface","from_refs":["v141-c-R017::x::v141-c-R017-x-d_t","v141-c-R017::x::v141-c-R017-x-p_t","v141-c-R017::x::v141-c-R017-x-delta_v"],"to_refs":["v141-c-R018::theta::v141-c-R018-P002","v141-c-R018::theta::v141-c-R018-P004","v141-c-R018::theta::v141-c-R018-P003"],"evidence_ids":["v141-b-g02-e037","v141-b-g02-e038"],"rationale":"The clearing selection is used in settlement as a fixed quantity input, and the local roles of variable and parameter are retained."},{"connection_id":"v142-d-K005-J04","from_chain_id":"v141-c-R017","to_chain_id":"v141-c-R018","kind":"functional_coupling","from_refs":["v141-c-R017::phi::v141-c-R017-C005"],"to_refs":["v141-c-R018::phi::v141-c-R018-C002"],"evidence_ids":["v141-b-g02-e037","v141-b-g03-E07","v141-b-g04-e20"],"rationale":"The temporal nodal balance is a relevant input to revenue reconciliation, but the flow-direction signs in the two source citations conflict; this mapping records a coupling pending verification and does not assert that all current expressions are already consistent."}],"object_mappings":[{"mapping_id":"v142-d-K005-O01","kind":"same_quantity","member_refs":["v141-c-R016::theta::v141-c-R016-TH001","v141-c-R017::theta::v141-c-R017-theta-alpha_p_t"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"],"rationale":"The same hourly supply quoted price enters temporal clearing."},{"mapping_id":"v142-d-K005-O02","kind":"same_quantity","member_refs":["v141-c-R016::theta::v141-c-R016-TH002","v141-c-R017::theta::v141-c-R017-theta-bar_p_t"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e033","v141-b-g02-e037"],"rationale":"The same hourly supply capacity bounds the generation quota."},{"mapping_id":"v142-d-K005-O03","kind":"same_quantity","member_refs":["v141-c-R017::x::v141-c-R017-x-d_t","v141-c-R018::theta::v141-c-R018-P002"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e037","v141-b-g02-e038"],"rationale":"The same nominal cleared-load quantity is converted into a fixed settlement input, and its distinction from the net physical load is retained."},{"mapping_id":"v142-d-K005-O04","kind":"same_quantity","member_refs":["v141-c-R017::x::v141-c-R017-x-p_t","v141-c-R018::theta::v141-c-R018-P004"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e037","v141-b-g04-e20"],"rationale":"The same hourly cleared generation quantity is used as a fixed input in revenue reconciliation."},{"mapping_id":"v142-d-K005-O05","kind":"same_quantity","member_refs":["v141-c-R017::x::v141-c-R017-x-delta_v","v141-c-R018::theta::v141-c-R018-P003"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e037","v141-b-g02-e038"],"rationale":"The same temporal load-shifting quota enters the price-difference remuneration; the two local objects are not merged."}],"gaps":[{"gap_id":"v142-d-K005-G01","category":"upstream_missing","description":"The C.2 candidate of R015 was not adopted; the existing chain retains only the demand-declaration fact and has no corresponding parameter objects for the price and the requested quantity. Objects from R017 must not be backfilled as content already present in R015.","chain_ids":["v141-c-R015","v141-c-R017"],"object_refs":["v141-c-R015::phi::v141-c-R015-C001"],"evidence_ids":["v141-b-g02-e033"],"proposal_ids":[],"required_work":"Handle the C2_nonmathematical_has_math contract issue according to a subsequent explicit revision by C; the existing chain remains unchanged."},{"gap_id":"v142-d-K005-G02","category":"math_incomplete","description":"R017-C003 has no objective expression; the demand term in source (2.31a) uses a consumer index, whereas the temporal declaration uses a period index, and the demand set and the corresponding definition are not closed.","chain_ids":["v141-c-R017"],"object_refs":["v141-c-R017::phi::v141-c-R017-C003","v141-c-R017::theta::v141-c-R017-theta-alpha_d_t"],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e037","v141-b-g03-E07"],"proposal_ids":[],"required_work":"B confirms the index and definition of the demand objective, and C then makes the formalization explicit; D does not presume the corrected objective."},{"gap_id":"v142-d-K005-G03","category":"scope_conflict","description":"In the temporal balance of g02-e037, received load shifting increases physical load, whereas the same equation recorded in g03-E07 uses the opposite in/out signs. The reconciliations in R017-C005 and R018 follow the former convention, so the two source records cannot be claimed to be consistent.","chain_ids":["v141-c-R017","v141-c-R018"],"object_refs":["v141-c-R017::phi::v141-c-R017-C005","v141-c-R018::phi::v141-c-R018-C002"],"evidence_ids":["v141-b-g02-e035","v141-b-g02-e037","v141-b-g03-E05","v141-b-g03-E07"],"proposal_ids":[],"required_work":"Independently check (2.30), (2.31b), and the in/out and rec/snd set definitions; after the source records are unified, check the settlement signs."},{"gap_id":"v142-d-K005-G04","category":"ambiguous_mapping","description":"In different citations, temporal-link capacity is written respectively as a capacity with a time subscript, a quantity without an overline, and a capacity with a link subscript; temporal computing capacity is also not defined separately in that section.","chain_ids":["v141-c-R017"],"object_refs":["v141-c-R017::theta::v141-c-R017-theta-bar_delta_v","v141-c-R017::theta::v141-c-R017-theta-bar_d_max_t","v141-c-R017::phi::v141-c-R017-C004"],"evidence_ids":["v141-b-g02-e034","v141-b-g02-e037","v141-b-g03-E06"],"proposal_ids":[],"required_work":"B confirms the per-link capacity notation and the meaning of temporal computing capacity; C makes the respective indices explicit, and the existing expressions are retained."},{"gap_id":"v142-d-K005-G05","category":"upstream_missing","description":"The temporal settlement narrative does not independently define the clearing-price symbol or its dual domain; the temporal price object used by R018 retains its original candidate status. The nonnegative price domain of the static model cannot be inherited.","chain_ids":["v141-c-R017","v141-c-R018"],"object_refs":["v141-c-R018::theta::v141-c-R018-P001","v141-c-R018::phi::v141-c-R018-C001"],"evidence_ids":["v141-b-g02-e037","v141-b-g02-e038","v141-b-g04-e16"],"proposal_ids":[],"required_work":"Make explicit the price symbol, the domain, and the general-model units of the temporal nodal balance, and distinguish gross remuneration from profit after deduction of the load-shifting cost."},{"gap_id":"v142-d-K005-G06","category":"scope_conflict","description":"The original market meaning of R018-C002 is limited to the scenarios reported in Table 5; these cases also have a four-period boundary and generation-ramping conditions. The R017 general model does not deliver these conditions, so the case results cannot be directly upgraded to a complete proof of the general rule.","chain_ids":["v141-c-R017","v141-c-R018"],"object_refs":["v141-c-R018::phi::v141-c-R018-C002"],"evidence_ids":["v141-b-g04-e13","v141-b-g04-e14","v141-b-g04-e20"],"proposal_ids":[],"required_work":"Keep the applicable domains of the cases and of the general model; if a case is to be reproduced, C must first explicitly add its boundary and ramping conditions."},{"gap_id":"v142-d-K005-G07","category":"ontology_extension","description":"The temporal load-shifting path, the service, and the computing capacity remain internal quantities and constraints; the related proposal has not been approved.","chain_ids":["v141-c-R017","v141-c-R018"],"object_refs":["v141-c-R017::x::v141-c-R017-x-delta_v","v141-c-R017::phi::v141-c-R017-C004"],"evidence_ids":["v141-b-g02-e034","v141-b-g02-e037","v141-b-g02-e038"],"proposal_ids":["v141-b-g02-p-virtual-link","v141-b-g02-p-load-shifting-service","v141-b-g03-P2-computing-capacity-constraint"],"required_work":"Manually review the temporal applicability of the proposal, and do not insert new graph nodes."},{"gap_id":"v142-d-K005-G08","category":"unverified_source","description":"All supporting citations and case narratives in this cluster remain unverified; no independent source audit or independent C2 review has been conducted.","chain_ids":["v141-c-R015","v141-c-R016","v141-c-R017","v141-c-R018"],"object_refs":[],"evidence_ids":["v141-b-g02-e033","v141-b-g02-e034","v141-b-g02-e037","v141-b-g02-e038","v141-b-g03-E06","v141-b-g03-E07","v141-b-g04-e20"],"proposal_ids":[],"required_work":"Make a scientific judgment only after checking the conflicts in the source records and the case conditions; this round provides only a partial assembly pending manual inspection."}]},"rule_refs":["42-data_center_space_time_flexibility::v141-c-R015","42-data_center_space_time_flexibility::v141-c-R016","42-data_center_space_time_flexibility::v141-c-R017","42-data_center_space_time_flexibility::v141-c-R018"],"unresolved_rule_refs":[],"node_ids":["COMP-4e6e38b5b14aacbf","COMP-ebacec241379c91d","KG40-c62513665ebf8550","KG40-ea70ad747d712a0c"]});
